  /// Clone the caller-named repository and ref into the run-owned tree.
  action provision(subject_repo: String, ref_requested: String, workspace_root: String, workflow_id: String) -> ProvisionProbe
    run json "bash workflows/repo-battery/bin/provision.sh $subject_repo $ref_requested $workspace_root $workflow_id"
  /// Read `gates.json:.legs` once at the single selector site and attest the
  /// declaration and subject instruments.
  action census(tree_path: String) -> CensusProbe
    run json "bash workflows/repo-battery/bin/census-declaration.sh $tree_path"
  /// Record venue toolchain, targets, PATH order, hydration, declared
  /// environment values or digests, and operation-script witnesses.
  action precheck(tree_path: String) -> PrecheckProbe
