  /// Invoke the provisioned tree's own bash battery under process-group
  /// containment. Red is data; cancellation is CANCELLED MEASUREMENT.
  action run_battery(tree_path: String, workspace_root: String, workflow_id: String) -> BatteryProbe
    run json "bash workflows/repo-battery/bin/run-battery.sh $tree_path $workspace_root $workflow_id"
  /// Invoke the provisioned tree's own declaration verifier against the one
  /// battery log and return its names-only verdict as typed data.
  action verify(tree_path: String, log_path: String) -> VerifyProbe
    run json "bash workflows/repo-battery/bin/verify.sh $tree_path $log_path"
  /// Remove only the run-owned tree with the deletion guard in this same
  /// script. Refusal obligations are returned, never assumed away.
  action teardown(workspace_root: String, workflow_id: String) -> TeardownProbe
    run json "bash workflows/repo-battery/bin/teardown.sh $workspace_root $workflow_id"

