  ok: Bool,
  refusal: String,
  venue: String?,
  toolchain: String?,
  targets: [String]?,
  environment: [EnvRecord]?,
  script_witnesses: [ScriptWitness]?,
}

type BatteryProbe {
  measured: Bool?,
  cancelled: Bool?,
  rc: Int?,
  contended: Bool?,
  log_path: String?,
  refusal: String,
}

type VerifyProbe {
  ok: Bool,
  verify_rc: Int,
  verify_verdict: String,
  verdict: String,
  legs_executed: [String],
  legs: [LegRecord],
